package dev.ensisdev.enspillars.config
import dev.ensisdev.enspillars.EnsPillarsPlugin
class ConfigurationService(private val plugin:EnsPillarsPlugin){fun reload()=Unit;val language get()=plugin.config.getString("settings.language","tr")?:"tr";val debug get()=plugin.config.getBoolean("settings.debug",false);val storageType get()=plugin.config.getString("storage.type","YAML")?:"YAML";val arenaDirectory get()=plugin.config.getString("arenas.directory","arenas")?:"arenas";val spawnHeight get()=plugin.config.getInt("setup.spawn-height",5).coerceIn(1,20);val globalLobby get():org.bukkit.Location?{val l=plugin.config.getList("global-lobby")?.mapNotNull{it?.toString()}?:return null;if(l.size<4)return null;val w=org.bukkit.Bukkit.getWorld(l[0])?:return null;return runCatching{org.bukkit.Location(w,l[1].toDouble(),l[2].toDouble(),l[3].toDouble(),l.getOrNull(4)?.toFloat()?:0f,l.getOrNull(5)?.toFloat()?:0f)}.getOrNull()}}
